import z3
import itertools

n = 10
vertices = list(range(n))

def test_without(constraint_name):
    solver = z3.Solver()
    edge_var = {}
    for i, j in itertools.combinations(vertices, 2):
        edge_var[(i,j)] = z3.Bool(f"e_{i}_{j}")
    def get_edge(i, j):
        if i < j:
            return edge_var[(i,j)]
        else:
            return edge_var[(j,i)]

    # Min degree >=3
    for i in vertices:
        incident = [get_edge(i, j) for j in vertices if j != i]
        solver.add(z3.AtLeast(*incident, 3))
    # Max degree <=5
    for i in vertices:
        incident = [get_edge(i, j) for j in vertices if j != i]
        solver.add(z3.AtMost(*incident, 5))
    # Edges 10-28
    all_edges = list(edge_var.values())
    solver.add(z3.AtLeast(*all_edges, 10))
    solver.add(z3.AtMost(*all_edges, 28))

    if constraint_name != 'C3':
        for i, j, k in itertools.combinations(vertices, 3):
            solver.add(z3.Not(z3.And(get_edge(i,j), get_edge(i,k), get_edge(j,k))))
    if constraint_name != 'C4':
        for a, b, c, d in itertools.combinations(vertices, 4):
            cycles = [
                [(a,b), (b,c), (c,d), (a,d)],
                [(a,b), (b,d), (c,d), (a,c)],
                [(a,c), (b,c), (b,d), (a,d)],
            ]
            for cyc in cycles:
                solver.add(z3.Not(z3.And([get_edge(*e) for e in cyc])))
    if constraint_name != 'alpha':
        for four in itertools.combinations(vertices, 4):
            edges_among = [get_edge(i,j) for i,j in itertools.combinations(four, 2)]
            solver.add(z3.Or(edges_among))
    if constraint_name != 'chi':
        color_vars = [z3.Int(f"c_{i}") for i in vertices]
        for i in vertices:
            solver.add(color_vars[i] >= 0, color_vars[i] <= 3)
        for i, j in itertools.combinations(vertices, 2):
            solver.add(z3.Implies(get_edge(i,j), color_vars[i] != color_vars[j]))

    result = solver.check()
    return result

for name in ['all', 'C3', 'C4', 'alpha', 'chi']:
    res = test_without(name)
    print(f"Without {name}: {res}")
